import collections
import json
import os
def task_func(directory_path: str) -> dict:
    """
    Count the total appearances of all keys in all JSON files in the specified directory.

    Parameters:
    - directory_path (str): The path to the directory containing JSON files.

    Returns:
    - dict: A dictionary with the keys from the JSON files as keys and their respective counts as values.

    Requirements:
    - collections
    - json
    - os

    Example:
    >>> task_func('/path/to/json/files')
    {'name': 5, 'age': 3, 'city': 2}
    """
    key_counter = collections.Counter()

    # Check if directory exists
    if not os.path.isdir(directory_path):
        return dict(key_counter)

    # Iterate through all files in the directory
    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)

            try:
                with open(file_path, 'r', encoding='utf-8') as file:
                    data = json.load(file)

                    # Recursively extract all keys from JSON data
                    def extract_keys(obj, current_keys=None):
                        if current_keys is None:
                            current_keys = []

                        if isinstance(obj, dict):
                            for key in obj.keys():
                                current_keys.append(key)
                                extract_keys(obj[key], current_keys)
                        elif isinstance(obj, list):
                            for item in obj:
                                extract_keys(item, current_keys)

                        return current_keys

                    # Extract all keys from the JSON data
                    all_keys = extract_keys(data)

                    # Update the counter with all keys found
                    key_counter.update(all_keys)

            except (json.JSONDecodeError, IOError, PermissionError):
                # Skip files that can't be read or parsed
                continue

    # Convert Counter to regular dictionary
    return dict(key_counter)

