import json
import os
from glob import glob
def task_func(directory, string):
    """
    Search for a specific string within the JSON data of files in a given directory and its subdirectories.

    Parameters:
    - directory (str): The directory path to search in
    - string (str): The string to search for (case-sensitive)

    Returns:
    - list: A list of file paths (str) containing the string within their JSON data

    Notes:
    - Recursively scans for JSON files
    - Searches within the JSON structure (keys and values)
    - Returns empty list if no matches found or no JSON files exist
    """
    result_files = []

    # Recursively find all JSON files in directory and subdirectories
    json_files = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.lower().endswith('.json'):
                json_files.append(os.path.join(root, file))

    # If no JSON files found, return empty list
    if not json_files:
        return []

    # Search each JSON file for the string
    for file_path in json_files:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError:
                    # Skip invalid JSON files
                    continue

                # Recursive function to search for string in JSON structure
                def search_in_json(obj, target):
                    """Recursively search for target string in JSON object"""
                    if isinstance(obj, dict):
                        # Check keys
                        for key in obj.keys():
                            if isinstance(key, str) and target in key:
                                return True
                        # Check values recursively
                        for value in obj.values():
                            if search_in_json(value, target):
                                return True
                    elif isinstance(obj, list):
                        for item in obj:
                            if search_in_json(item, target):
                                return True
                    elif isinstance(obj, str):
                        return target in obj
                    elif isinstance(obj, (int, float, bool)):
                        # Convert to string and check
                        return target in str(obj)
                    elif obj is None:
                        return False
                    return False

                # If string found in JSON structure, add file to results
                if search_in_json(data, string):
                    result_files.append(file_path)

        except (IOError, OSError):
            # Skip files that can't be read
            continue

    return result_files

